import path from 'path';

import {
  DEFAULT_AI_FUNCTIONS,
  DEFAULT_AI_LIBRARIES
} from './constants.js';

const JS_EXTENSIONS = new Set(['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.mts', '.cts']);
const PYTHON_EXTENSIONS = new Set(['.py']);

const uniqPush = (store, key, value) => {
  const list = store[key] || (store[key] = []);
  if (!list.includes(value)) {
    list.push(value);
  }
};

const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Strips // and /* */ comments while leaving string contents (which may hold
// import specifiers) untouched.
function stripJsComments(source) {
  let out = '';
  let i = 0;
  const n = source.length;
  while (i < n) {
    const c = source[i];
    const next = source[i + 1];
    if (c === '/' && next === '/') {
      while (i < n && source[i] !== '\n') i++;
      continue;
    }
    if (c === '/' && next === '*') {
      i += 2;
      while (i < n && !(source[i] === '*' && source[i + 1] === '/')) i++;
      i = Math.min(i + 2, n);
      continue;
    }
    if (c === '"' || c === "'" || c === '`') {
      const quote = c;
      out += c;
      i++;
      while (i < n && source[i] !== quote) {
        if (source[i] === '\\' && i + 1 < n) {
          out += source[i] + source[i + 1];
          i += 2;
          continue;
        }
        out += source[i];
        i++;
      }
      if (i < n) {
        out += source[i];
        i++;
      }
      continue;
    }
    out += c;
    i++;
  }
  return out;
}

// Strips # comments and drops docstring bodies while respecting quoted strings.
function stripPythonComments(source) {
  let out = '';
  let i = 0;
  const n = source.length;
