    const c = source[i];
    if (c === '#') {
      while (i < n && source[i] !== '\n') i++;
      continue;
    }
    if (c === '"' || c === "'") {
      const quote = c;
      const isTriple = source[i + 1] === quote && source[i + 2] === quote;
      if (isTriple) {
        i += 3;
        while (i < n && !(source[i] === quote && source[i + 1] === quote && source[i + 2] === quote)) {
          i++;
        }
        i = Math.min(i + 3, n);
        continue;
      }
      out += c;
      i++;
      while (i < n && source[i] !== quote && source[i] !== '\n') {
        if (source[i] === '\\' && i + 1 < n) {
          out += source[i] + source[i + 1];
          i += 2;
          continue;
        }
        out += source[i];
        i++;
      }
      if (i < n && source[i] === quote) {
        out += source[i];
        i++;
      }
