  id: 'libraries',
  analyze({ content, filePath, result }) {
    const view = collectImportView(content, filePath);

    for (const library of libraries) {
      const matched = view.mode === 'specifiers'
        ? Array.from(view.specifiers).some((specifier) => matchesLibrary(specifier, library))
        : genericLibraryMatches(view.content, library);

      if (matched) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

