      `(?:\\bimport\\b|\\bfrom\\b|\\brequire\\b|\\blibrary\\b)\\s*\\(?\\s*['"\`]?${escaped}(?![\\w-])`,
      'i'
    );
    genericMatchers.set(library, regex);
  }
  return regex.test(strippedContent);
}

function collectImportView(content, filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (JS_EXTENSIONS.has(ext)) {
    return { mode: 'specifiers', specifiers: extractJsSpecifiers(content) };
  }
  if (PYTHON_EXTENSIONS.has(ext)) {
    return { mode: 'specifiers', specifiers: extractPythonSpecifiers(content) };
  }
  return { mode: 'generic', content: stripGenericComments(content) };
}

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    const view = collectImportView(content, filePath);

    for (const library of libraries) {
      const matched = view.mode === 'specifiers'
        ? Array.from(view.specifiers).some((specifier) => matchesLibrary(specifier, library))
        : genericLibraryMatches(view.content, library);

      if (matched) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

export const createFunctionDetector = (functions = DEFAULT_AI_FUNCTIONS) => ({
  id: 'functions',
  analyze({ content, filePath, result }) {
    for (const func of functions) {
      const regex = new RegExp(`[\\s\\.\\(]${func}\\s*\\(`, 'g');
      if (regex.test(content)) {
        uniqPush(result.aiFunctionMatches, filePath, func);
        result.markAiFile(filePath);
      }
    }
  }
});

export const DEFAULT_DETECTORS = [
  createLibraryDetector(),
  createFunctionDetector()
];

